function finishHighlights(){if(!cinematic)return;const done=cinematic.done;cinematic=null;done();}
function debriefNavigation(scope){return `<div class="debrief-navigation"><strong>${scope}</strong>${button('Skip','debrief-skip','small','title="Passer le débriefing"')}</div>`;}
function report(previous){playCue('transmission');const entries=E.visibleLogs(state).filter(l=>l.id>previous),turn=state.ended?state.turn:state.turn-1;const logs=items=>items.length?items.map(l=>`<p class="${l.type}">${esc(l.text)}</p>`).join(''):'<p class="muted">Aucun nouvel événement.</p>';showModal(`<div class="simple-modal report-modal">${debriefNavigation('DÉBRIEFING · TOUR '+turn)}<h2>${state.ended?'L’opération est terminée.':'Bilan du tour'}</h2><div class="debrief-columns"><section class="debrief-section"><span class="eyebrow">01 · VOTRE ÉQUIPE</span><h3>Bilan du joueur · ${COUNTRY[state.player].name}</h3>${reportUpdates(state,'player')}${reportCards(state,turn)}<details><summary>Journal de votre équipe</summary>${logs(entries.filter(l=>l.faction===state.player))}</details></section><section class="debrief-section debrief-world"><span class="eyebrow">02 · SITUATION MONDIALE</span><h3>Bilan mondial</h3>${reportUpdates(state,'world')}${logs(entries.filter(l=>!l.faction))}</section></div>${lastHighlights.length?button('Revoir les temps forts','milestone-replay','small','data-id="'+previous+'"'):''}${button(state.ended?'Consulter le bilan':state.event?'Ouvrir la communication':'Retour au commandement','after-report','primary wide')}</div>`,'compact-report-dialog');}
function eventModal(){const ev=state.event;if(!ev)return;showModal(`<div class="dialogue-modal"><div class="dialogue-portrait">${portrait(ROSTER[0])}<span>CANAL PRIVÉ / 04</span></div><div class="dialogue-copy"><span class="eyebrow">COMMUNICATION ENTRANTE</span><h2>${ev.title}</h2><div class="speech-bubble"><strong>${ev.speaker}</strong><p>${ev.text}</p></div><div class="dialogue-consult">${button(icon('world')+' Consulter le jeu avant de répondre','consult-game','wide')}<small>La communication reste en attente. Le tour n’avance pas.</small></div><div class="dialogue-options">${ev.choices.map((c,i)=>{const reason=E.eventChoiceUnavailable(state,i);return `<button data-cmd="event" data-id="${i}" ${reason?'disabled':''}><span>0${i+1}</span><div><strong>${c.label}</strong><small>${c.detail}</small>${reason?`<small class="disabled-reason">${esc(reason)}</small>`:''}</div>${icon('chevron')}</button>`;}).join('')}</div></div></div>`,'dialogue-shell');}
function ending(){modal.close();view='ending';reportTab='overview';reportCountry=state.player;render();}
function recruitModal(){
 const pending=state.recruitments.filter(r=>r.faction===state.player);
 const candidates=E.recruitmentCandidates(state);
 const needsReplace=E.team(state).length+pending.length>=4;
 const relievable=E.team(state).filter(a=>!a.task&&a.country===state.player&&a.status!=='captured');
 const blocked=!!state.ended||needsReplace&&!relievable.length;
 showModal(`<div class="simple-modal"><span class="eyebrow">BUREAU DE RECRUTEMENT</span><h2>Renforts & relève</h2><p>Le recrutement est gratuit et prend deux tours. Votre unité reste limitée à quatre postes.</p>${pending.map(r=>`<p class="notice">${icon('clock')} ${esc(FULL_ROSTER.find(a=>a.id===(r.templateId||r.id))?.name||r.id)} est recruté · arrivée dans ${r.remaining} tour(s).</p>`).join('')}${needsReplace?`<label>Agent relevé au QG<select id="replaceAgent"><option value="">Choisir un agent disponible au QG</option>${relievable.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></label><p class="muted">La relève est définitive. Les agents capturés conservent leur poste.</p>`:''}${state.ended?'<p class="notice warning">La campagne est terminée.</p>':needsReplace&&!relievable.length?'<p class="notice warning">Aucun agent disponible au QG pour une relève.</p>':''}${candidates.length?candidates.map(a=>`<div class="recruit-option">${portrait(a)}<div><h3>${esc(a.name)} ${nationalityFlags(a)}</h3><p>${esc(a.role)}</p>${statlines(a)}${button('Recruter · gratuit','hire','small',`data-id="${a.id}" ${blocked?'disabled':''}`)}</div></div>`).join(''):'<p>La réserve disponible est épuisée.</p>'}<p id="recruitError" class="notice warning" role="alert" hidden></p></div>`);
}
function recruitFailure(error){const message=$('#recruitError');if(message){message.textContent=error.message;message.hidden=false;}else toast(error.message);}
function help(){showModal(`<div class="simple-modal settings-modal"><span class="eyebrow">PRÉFÉRENCES DU JEU</span><h2>Paramètres</h2>${settingsMarkup()}</div>`);}
function wikiUtilities(){return `<section class="panel wiki-utilities"><h2>Votre campagne</h2><div class="command-shortcuts">${button('Briefing','briefing','small')}${(state?.turnActivities?.length||state?.cellReports?.length||state?.attackReports?.length||state?.threatReports?.length||state?.attackDelayReports?.length)?button('Dernier débriefing','reveal-replay','small'):''}${button('Exporter la sauvegarde','export','small')}${button('Importer une sauvegarde','import','small')}${button('Copie avant refonte des crédits','export-economy-backup','small')}</div><input type="file" id="saveFile" accept="application/json,.json" hidden></section>`;}

function nextTurn(){if(state.ended){ending();return;}if(multiplayer.active&&multiplayer.me?.ready){multiplayer.command('ready',{ready:false}).catch(e=>toast(e.message));return;}if(state.ended){ending();return;}if(state.event){eventModal();return;}const idle=E.team(state).filter(a=>!a.task&&a.status!=='captured');if(idle.length){showModal(`<div class="simple-modal"><span class="eyebrow">CONFIRMER LA FIN DU TOUR</span><h2>${idle.length} agent(s) sans ordre</h2><p>${idle.map(a=>a.name).join(', ')} resteront inactifs. Ils ne récupéreront pas de fatigue sans ordre de repos.</p><div class="suspect-actions">${button('Revenir aux ordres','close')}${button('Terminer quand même','advance-confirm','primary')}</div></div>`);}else finishTurn();}
function finishTurn(){if(multiplayer.active){modal.close();multiplayer.command('ready',{ready:true}).catch(e=>toast(e.message));return;}const previous=state.logId,turn=state.turn,before=investigationSnapshot(state);try{clearSignals();E.advance(state);lastHighlights=investigationHighlights(before,state);persist();render();turnSignals(state,turn);showReveals(()=>showHighlights(lastHighlights,()=>report(previous)));}catch(e){toast(e.message);}}
document.addEventListener('click',event=>{
 const confirmed=event.target.closest('[data-cmd="confirm-government"]');if(confirmed){const o=E.governmentOptions(state,'diplomacy',confirmed.dataset.id);if(multiplayer.observer||o.error||o.cost!==Number(confirmed.dataset.cost)){event.stopImmediatePropagation();modal.close();toast(o.error||'La situation a changé. Vérifiez à nouveau la démarche.');}return;}
 const el=event.target.closest('[data-cmd="government-favor"][data-id="diplomacy"]');if(!el||el.disabled)return;
 event.stopImmediatePropagation();if(multiplayer.observer)return;
 const country=$('#governmentCountry')?.value,o=E.governmentOptions(state,'diplomacy',country);
 if(o.error){toast(o.error);return;}
 showModal(`<div class="simple-modal"><h2>Confirmer la démarche diplomatique</h2><h3>${flag(country)} ${COUNTRY[country].name}</h3><p>Coût : <strong>${o.cost} confiance</strong></p><p>Augmenter la coopération d’un niveau.</p><div class="suspect-actions">${button('Annuler','close')}${button('Valider','confirm-government','primary',`data-id="${country}" data-cost="${o.cost}"`)}</div></div>`);
});
// Route every multiplayer mutation through the authoritative host, including host UI actions.
document.addEventListener('click',event=>{
 const el=event.target.closest('[data-cmd]');if(!el||el.disabled)return;const cmd=el.dataset.cmd,id=el.dataset.id;
 if(cmd.startsWith('mp-')){event.stopImmediatePropagation();multiplayer.handle(cmd,id).catch(e=>toast(e.message));return;}
 if(cmd==='confirm-deployment'){event.stopImmediatePropagation();confirmDeployment().catch(e=>toast(e.message));return;}
 if(!multiplayer.active)return;
 if(multiplayer.observer){if(['deploy','travel','agent-rest','recruit','confidence','government-favor','tech','tech-drone','confirm-order','cancel','confirm-cancel','cancel-tech','confirm-cancel-tech','cancel-cyber','confirm-cancel-cyber','hire','event','request-accept','request-decline','advance-confirm'].includes(cmd)){event.stopImmediatePropagation();toast('Observateur : consultation uniquement.');return;}}
 if(['new','new-confirm','start','resume','import'].includes(cmd)){event.stopImmediatePropagation();toast('Quittez la session depuis le salon pour ouvrir une campagne solo.');return;}
 if(cmd==='export'){event.stopImmediatePropagation();try{multiplayer.export();}catch(e){toast(e.message);}return;}
 const mutations={
  'confirm-order':['assign',()=>({id:order.id,type:order.type,target:order.target||null,useCredits:!!order.useCredits})],
  'confirm-cancel':['cancel',()=>({id})], 'confirm-cancel-tech':['cancel-tech',()=>({id})], 'confirm-cancel-cyber':['cancel-cyber',()=>({country:id})],'confirm-government':['government-favor',()=>({type:'diplomacy',country:id})],'government-favor':['government-favor',()=>({type:id,country:$('#governmentCountry')?.value||null})],tech:['tech',()=>({type:id,country:$('#guardCountry')?.value||selectedCountry})],
  'request-accept':['request',()=>({plot:id,accept:true})], 'request-decline':['request',()=>({plot:id,accept:false})],
  event:['event',()=>({index:Number(id)})],hire:['hire',()=>({id,replaceId:$('#replaceAgent')?.value||null})]
 };
 if(mutations[cmd]){event.stopImmediatePropagation();if(cmd==='confirm-order'&&modal.dataset.orderAgent!==order.id){toast('Sélection de l’agent modifiée : rouvrez son ordre.');return;}const [kind,payload]=mutations[cmd];multiplayer.command(kind,payload()).then(()=>{if(kind==='tech'||kind==='assign'&&order.type==='drone'){selectTechnology(null);render();}if(kind==='cancel'||kind==='cancel-tech')clearSignals();if(kind==='hire'&&revealSession)paintReveal();else modal.close();if(kind==='hire')toast('Recrutement confirmé. Le poste affichera la recrue en attente pendant deux tours.');if(kind==='share')toast('Échange transmis. Un joueur humain doit accepter votre proposition.');}).catch(e=>kind==='hire'?recruitFailure(e):toast(e.message));}
},true);
document.addEventListener('change',event=>{
 if(event.target.name==='deployAgent'){const picker=event.target.closest('.deployment-picker'),count=picker.querySelectorAll('[name="deployAgent"]:checked').length;picker.querySelector('#deploymentCount').textContent=`${count} agent${count>1?'s':''} sélectionné${count>1?'s':''}`;const confirm=picker.querySelector('[data-cmd="confirm-deployment"]');confirm.disabled=!count;confirm.textContent=count?`Déployer ${count} agent${count>1?'s':''}`:'Déployer les agents';return;}
 if(event.target.id==='gameMode'&&setup&&!setupDraft&&Object.hasOwn(GAME_MODES,event.target.value)){setupMode=event.target.value;setupAgents=[];setupConfirmed=false;resetRecruitFilters('solo');render();return;}
 if(event.target.id==='mpGameMode'){multiplayer.command('game-mode',{mode:event.target.value}).catch(e=>toast(e.message));return;}
 if(event.target.dataset.recruitFilter){const {recruitMode,recruitFilter}=event.target.dataset,id=event.target.id;setRecruitFilter(recruitMode,recruitFilter,event.target.value);render();document.getElementById(id)?.focus();return;}
 if(event.target.name==='mpAgent'){const count=document.querySelectorAll('[name="mpAgent"]:checked').length;document.querySelector('#mpTeamCount').textContent=`${count} / 4 agents sélectionnés`;document.querySelector('[data-cmd="mp-team"]').disabled=count!==4;}
 if(event.target.id==='mpObserveCountry')multiplayer.observe(event.target.value);
 if(event.target.id==='mpChooseCountry')multiplayer.command('country',{country:event.target.value}).catch(e=>toast(e.message));
 if(event.target.id==='mpImport'){const file=event.target.files[0];if(!file)return;if(file.size>5000000){toast('Fichier trop volumineux.');return;}file.text().then(text=>{if(multiplayer.hasSave()&&!confirm('Remplacer la sauvegarde multijoueur locale par ce fichier ?'))return;return multiplayer.resume(JSON.parse(text));}).catch(e=>toast(e.message));}
});
document.addEventListener('click',event=>{const el=event.target.closest('[data-cmd]');if(!el||el.disabled)return;const cmd=el.dataset.cmd,id=el.dataset.id;if(cmd!=='map-agent')mapAgentActivation.cancel();switch(cmd){
 case 'inquiry-step':case 'inquiry-substep':case 'country-threat':case 'inquiry-open-agent':case 'country-inquiry':case 'inquiry-action':case 'inquiry-agent':case 'inquiry-boost':case 'inquiry-effects':case 'inquiry-confirm':handleInquiryCommand(cmd,id);break;
 case 'patch-notes':modal.close();menuPage='patch-notes';menuOpen=true;render();window.scrollTo(0,0);app.scrollTop=0;break;
 case 'main-menu':modal.close();menuPage='home';menuOpen=true;render();break;
 case 'continue-game':if(state){menuOpen=false;setup=false;render();}break;
 case 'mods':showModal(`<div class="simple-modal settings-modal"><h2>Mods</h2>${modsMarkup()}${button('Fermer','close')}</div>`);break;
 case 'settings':help();break;
 case 'music-next':nextTrack();break;
 case 'ai-difficulty':if(!setupDraft&&Object.hasOwn(AI_LEVELS,id)){setupDifficulty=id;render();}break;
 case 'country':if(!setupDraft){setupCountry=id;render();}break;
 case 'solo-confirm-country':if(setupMode==='advanced'&&!setupDraft){setupDraft=advanceNpcDraft(createDraft([setupCountry]));setupAgents=[];setupConfirmed=false;render();}break;
 case 'solo-draft-pick':if(setupDraft&&draftCountry(setupDraft)===setupCountry){try{pickDraftAgent(setupDraft,setupCountry,id);advanceNpcDraft(setupDraft);if(!draftCountry(setupDraft))setupAgents=[...setupDraft.teams[setupCountry]];render();}catch(e){toast(e.message);}}break;
 case 'solo-draft-chief':case 'solo-draft-before':case 'solo-draft-after':if(setupDraft&&!draftCountry(setupDraft)){setupAgents=reorderTeam(setupAgents,id,cmd.split('-').at(-1));setupConfirmed=false;render();}break;
 case 'solo-confirm-team':if(setupDraft&&!draftCountry(setupDraft)&&setupAgents.length===4){setupConfirmed=true;render();}break;
 case 'select-recruit':if(setupMode==='advanced')break;if(!setupAgents.includes(id)&&setupAgents.length===4)toast('Désélectionnez un agent avant d’en choisir un autre.');else setupAgents=toggleRecruitSelection(setupAgents,id,'solo');render();break;
 case 'recruit-details':showModal(recruitDetails(id),'recruit-dossier-modal');break;
 case 'recruit-flip':updateRecruitFaces(document,el.dataset.recruitMode,id,!isRecruitPortrait(id,el.dataset.recruitMode));break;
 case 'recruit-view':updateRecruitFaces(document,el.dataset.recruitMode,null,id==='portrait');break;
 case 'start':if(setupMode==='advanced'&&(!setupDraft||draftCountry(setupDraft)||!setupConfirmed)){toast('Terminez le repêchage et confirmez votre équipe.');break;}menuOpen=false;resetExperience();clearSignals();state=E.createConfiguredGame(setupCountry,setupAgents,Date.now(),setupDifficulty,setupDraft?{gameMode:'advanced',participants:setupDraft.countries,teams:{...setupDraft.teams,[setupCountry]:[...setupAgents]}}:{gameMode:'regular'});setup=false;view='world';selectedCountry=state.player;selectedAgent=null;camera.k=1.65;focusCountry(camera,state.player);persist();render();toast('Commandement établi. Le briefing est disponible depuis le bouton « ? ».');break;
 case 'resume':menuOpen=false;setup=false;render();break;
 case 'new':modal.close();if(state&&!state.ended){showModal(`<div class="simple-modal"><h2>Préparer une nouvelle campagne ?</h2><p>Votre sauvegarde actuelle sera remplacée au lancement de la nouvelle opération. Vous pouvez l’exporter avant de continuer.</p><div class="suspect-actions">${button('Exporter','export')}${button('Choisir une nouvelle équipe','new-confirm','primary')}</div></div>`);}else{menuOpen=false;resetRecruitFilters('solo');setupAgents=[];setupMode='regular';setupDraft=null;setupConfirmed=false;setup=true;render();}break;
 case 'new-confirm':modal.close();menuOpen=false;resetRecruitFilters('solo');setupAgents=[];setupMode='regular';setupDraft=null;setupConfirmed=false;setup=true;render();break;
 case 'bureau':if(bureauEnabled()){view='bureau';inquiryTracker.read(state,inquiryRoom());render();openBureau();}break;
 case 'nav':closeBureau();view=id;inquiryTracker.read(state,inquiryRoom(),id);render();break;
 case 'map-agent':mapAgentActivation.click(id);break;
 case 'map-country':{const now=Date.now(),double=lastCountryClick.id===id&&now-lastCountryClick.time<450;lastCountryClick={id,time:now};camera.panelOpen=true;selectedAgent=null;selectedCountry=id;focusCountry(camera,id);view='world';modal.close();render();if(double&&!multiplayer.observer)deploy();break;}
 case 'agent':openAgent(id);break;
 case 'suggest-action':openAgent(id,el.dataset.type,el.dataset.target||null);break;
 case 'agent-rest':{const a=state.agents.find(a=>a.id===id);if(a)openAgent(id,a.country===a.faction?'rest':E.hasSafehouse(state,a.faction,a.country)?'fieldRest':'hide');break;}
 case 'agent-journal':agentJournal(id);break;
 case 'select-agent':{const now=Date.now(),double=lastAgentClick.id===id&&now-lastAgentClick.time<400;lastAgentClick={id,time:now};modal.close();selectedAgent=id;view='agents';render();if(double)openAgent(id);break;}
 case 'focus-map':if(camera.mode==='dome')camera.k=Math.max(1.65,camera.k);focusCountry(camera,selectedCountry);render();break;
 case 'deploy':deploy();break;
 case 'pick-agent':openAgent(id,el.dataset.type,el.dataset.target||null);break;
 case 'confirm-order':try{if(modal.dataset.orderAgent!==order.id)throw Error('Sélection de l’agent modifiée : rouvrez son ordre.');E.assign(state,order.id,order.type,order.target||null,order.useCredits);if(order.type==='drone')selectTechnology(null);stageSignal(state.agents.find(a=>a.id===order.id));persist();modal.close();render();clearTimeout(toast.timer);orderFeedback(state,order.id);}catch(e){toast(e.message);}break;
 case 'cancel':{const a=state.agents.find(a=>a.id===id);if(!a?.task)break;if(E.travelInProgress(a)){toast('Un déplacement commencé ne peut pas être annulé.');break;}showModal(`<div class="simple-modal"><span class="eyebrow">ANNULER L’OPÉRATION</span><h2>Libérer ${esc(a.name)} ?</h2><p>${ACTIONS[a.task.type].name} sera abandonnée. Aucun résultat futur ne sera produit par cet ordre.</p><p>L’agent sera immédiatement disponible.${a.task.bonusCredits?a.task.queued?' Le renfort non commencé sera remboursé : '+a.task.bonusCredits+' crédits.':' Le renfort de cette mission commencée reste consommé.':''}${ACTIONS[a.task.type].tech?' Le Module sera également libéré.':''}</p><div class="suspect-actions">${button('Garder l’ordre','close')}${button('Annuler l’opération','confirm-cancel','primary','data-id="'+id+'"')}</div></div>`);break;}
 case 'confirm-cancel':clearSignals();if(change(()=>E.cancel(state,id)))modal.close();break;
 case 'cancel-tech':{const t=state.factions[state.player].tech.find(t=>t.id===id&&t.until>=state.turn);if(!t)break;showModal(`<div class="simple-modal"><span class="eyebrow">ANNULER LE MODULE</span><h2>Arrêter ${TECH[t.type].name} ?</h2><p>${t.type==='logistics'?'Les voyages déjà raccourcis conservent leur durée. Les nouveaux voyages ne recevront plus le bonus.':t.type==='relay'?'Les missions déjà accélérées et les prolongations de position acquises sont conservées. Les nouvelles localisations prennent de nouveau 2 tours et ne reçoivent plus le bonus de durée de validité.':t.type==='guard'?'La protection de cette sentinelle sera retirée. Les autres sources de protection resteront actives.':'Le bonus IA sera retiré des vérifications encore en cours. Ces missions indépendantes continueront ; annulez-les séparément pour libérer leurs agents.'}</p><p><b>${E.techRefund(state,t)} crédit(s) seront remboursés.</b> Le Module sera immédiatement libéré. Les résultats déjà obtenus restent acquis.</p><div class="suspect-actions">${button('Conserver le module','close')}${button('Arrêter le module','confirm-cancel-tech','primary','data-id="'+id+'"')}</div></div>`);break;}
 case 'cancel-cyber':if(COUNTRY[id])showModal(`<div class="simple-modal"><h2>Arrêter le hack d’un pays en ${COUNTRY[id].name} ?</h2><p>Le bonus sera retiré des opérations encore en cours dans ce pays. Les missions indépendantes continueront.</p><p>${E.cyberSupportRefund(state.factions[state.player].cyberSupport[id])} crédit(s) seront remboursés. Ce soutien n’occupe aucun Module ni opérateur dédié.</p><div class="suspect-actions">${button('Conserver le soutien','close')}${button('Annuler et rembourser','confirm-cancel-cyber','primary','data-id="'+id+'"')}</div></div>`);break;
 case 'confirm-cancel-cyber':if(change(()=>E.cancelCyberSupport(state,id)))modal.close();break;
 case 'confirm-cancel-tech':if(change(()=>E.cancelTech(state,id)))modal.close();break;
 case 'tech-select':{const main=app.querySelector('.deck-main'),scroll=main?.scrollTop||0;selectTechnology(id);render();const next=app.querySelector('.deck-main');if(next)next.scrollTop=scroll;break;}
 case 'tech-drone':{const agentId=$('#consoleDroneAgent')?.value;if(agentId)openAgent(agentId,'drone',null);break;}
 case 'advance':nextTurn();break;
 case 'advance-confirm':finishTurn();break;
 case 'debrief-skip':clearTimeout(showReveals.timer);revealSession=null;cinematic=null;modal.close();if(state.ended)ending();else if(state.event)eventModal();break;
 case 'after-report':if(state.ended)ending();else if(state.event)eventModal();else modal.close();break;
 case 'milestone-next':if(cinematic){const {items,index,done}=cinematic;if(index+1<items.length)showHighlights(items,done,index+1);else finishHighlights();}break;
 case 'milestone-skip':finishHighlights();break;
 case 'milestone-replay':showHighlights(lastHighlights,()=>report(Number(id)));break;
 case 'close':if(!revealSession&&!cinematic)modal.close();break;
 case 'consult-game':modal.close();render();break;
 case 'communication':eventModal();break;
 case 'suspect':handleInquiryCommand('country-inquiry',id);break;
 case 'mission-target':{const t=E.knownTargets(state).find(t=>t.id===id),next=E.nextOperation(state,t);deploy(next.type||'surveil',next.type==='analyze'?null:next.type==='contacts'?t.country:id);break;}
 case 'verify':deploy('analyze',id||null);break;
 case 'confirm-government':change(()=>E.requestGovernmentFavor(state,'diplomacy',id));modal.close();break;
 case 'government-favor':change(()=>E.requestGovernmentFavor(state,id,$('#governmentCountry')?.value||null));break;
 case 'national':modal.close();view='government';render();break;
 case 'tech':{const before=investigationSnapshot(state);if(change(()=>{E.activateTech(state,id,$('#guardCountry')?.value||selectedCountry);selectTechnology(null);}))showHighlights(investigationHighlights(before,state),()=>modal.close());break;}

 case 'request-accept':change(()=>E.answerRequest(state,id,true));break;
 case 'request-decline':change(()=>E.answerRequest(state,id,false));break;
 case 'event':try{const before=investigationSnapshot(state);E.answerEvent(state,Number(id));persist();modal.close();render();showHighlights(investigationHighlights(before,state),()=>modal.close());}catch(e){toast(e.message);}break;
 case 'reveal-now':paintReveal(true);break;
 case 'reveal-next':if(revealSession){if(++revealSession.index<revealSession.items.length)paintReveal();else finishReveals();}break;
 case 'reveal-skip':finishReveals();break;
 case 'reveal-replay':{const turn=state.turnActivities?.[0]?.turn||state.turn-1,previous=Math.max(0,...E.visibleLogs(state).filter(l=>l.turn<turn).map(l=>l.id));showReveals(()=>report(previous));break;}
 case 'ending':ending();break;
 case 'recruit':recruitModal();break;
 case 'hire':try{E.recruit(state,id,$('#replaceAgent')?.value||null);persist();render();if(revealSession)paintReveal();else modal.close();toast('Recrutement confirmé. Le poste affichera la recrue en attente pendant deux tours.');}catch(e){recruitFailure(e);}break;
 case 'briefing':showModal(`<div class="simple-modal"><h2>Briefing initial</h2><p>Deux pistes connues. Envoyez vos agents dans les pays concernés et gardez un analyste au QG. Ouvrez un accès, recueillez deux preuves et vérifiez-les. Préparez l’arrestation, obtenez un mandat et localisez la cible avant d’intervenir.</p>${button('Prendre le commandement','close','primary')}</div>`);break;
 case 'open-wiki':modal.close();view='wiki';render();break;
 case 'help':help();break;
 case 'test-sound':playCue('discovery');break;
 case 'dismiss-feedback':dismissNotices();render();break;
 case 'proof':proofModal(id);break;
 case 'export-economy-backup':{const raw=localStorage.getItem(ECONOMY_BACKUP_KEY);if(!raw){toast('Aucune ancienne campagne conservée dans ce navigateur.');break;}const url=URL.createObjectURL(new Blob([raw],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='sigma2040-avant-economie-v82.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Copie antérieure exportée.');break;}
 case 'export':{const blob=new Blob([JSON.stringify(state)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`sigma2040-tour-${state.turn}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sauvegarde exportée.');break;}
 case 'import':$('#saveFile').click();break;
 }});
document.addEventListener('change',async event=>{handleInquiryChange(event.target);if(event.target.id==='modBureau'){setBureauEnabled(event.target.checked);if(!bureauEnabled()){closeBureau();if(view==='bureau')view='world';}render();}if(event.target.id==='graphicsQuality')setGraphicsQuality(event.target.value);if(event.target.id==='musicEnabled'){setMusic('enabled',event.target.checked);$('#musicVolume').disabled=!event.target.checked;modal.querySelector('[data-cmd="music-next"]').disabled=!event.target.checked;}if(event.target.id==='feedbackSound'){updatePreference('sound',event.target.checked);$('#feedbackVolume').disabled=!event.target.checked;modal.querySelector('[data-cmd="test-sound"]').disabled=!event.target.checked;if(event.target.checked)playCue();}if(event.target.id==='feedbackMotion')updatePreference('motion',event.target.value);if(event.target.id==='mapSelect'){camera.panelOpen=true;selectedAgent=null;selectedCountry=event.target.value;focusCountry(camera,selectedCountry);render();}if(event.target.id==='orderType'){order.type=event.target.value;order.useCredits=false;orderModal();}if(event.target.id==='orderCredits'){order.useCredits=event.target.checked;orderModal();}if(event.target.id==='orderTarget'){order.target=event.target.value;orderModal();}if(event.target.id==='saveFile'){try{const file=event.target.files[0];if(!file)return;if(file.size>2000000)throw Error('Fichier trop volumineux.');const imported=E.validateSave(JSON.parse(await file.text()));showModal(`<div class="simple-modal"><h2>Importer cette campagne ?</h2><p>${COUNTRY[imported.player].name} · tour ${imported.turn}. La campagne actuelle sera remplacée.</p><div class="suspect-actions">${button('Annuler','close')}<button class="btn primary" id="confirmImport">Importer</button></div></div>`);$('#confirmImport').onclick=()=>{resetExperience();clearSignals();state=imported;menuOpen=false;setup=false;view='world';persist();modal.close();render();};}catch(e){toast(e.message);}}});
document.addEventListener('toggle',event=>{if(event.target.matches?.('.map-dossier'))camera.panelOpen=event.target.open;},true);
document.addEventListener('input',event=>{if(event.target.id==='musicVolume'){setMusic('volume',event.target.value);$('#musicVolumeValue').textContent=event.target.value+'%';}if(event.target.id==='feedbackVolume'){updatePreference('volume',event.target.value);$('#feedbackVolumeValue').textContent=event.target.value+'%';}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.map-pin-v2')){e.preventDefault();selectedCountry=e.target.dataset.id;render();}});
modal.addEventListener('cancel',e=>{if(revealSession||cinematic)e.preventDefault();});
modal.addEventListener('close',()=>{if(cinematic){finishHighlights();return;}const svg=document.querySelector('#strategicMap');if(svg)paintSignals(svg);});
bindBackdropDismiss(modal,()=>{if(!revealSession&&!cinematic)modal.close();});
async function loadMap(){try{const r=await fetch('./assets/world.json');if(!r.ok)throw Error('Carte indisponible.');world=await r.json();render();}catch(e){toast('Fond cartographique indisponible. Utilisez le sélecteur de pays.');}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const common={type:'object',properties:{},additionalProperties:false};const entries=[{name:'read_sigma_multiplayer',title:'Lire le salon Sigma',description:'Lire les places, connexions et états prêts ; uniquement les renseignements du pays courant.',inputSchema:common,annotations:{readOnlyHint:true},execute(){return multiplayer.snapshot||{active:multiplayer.active,status:multiplayer.status};}},{name:'open_sigma_multiplayer',title:'Ouvrir une session multijoueur Sigma',description:'Créer un salon avec sauvegarde chez l’hôte, rejoindre une invitation ou reprendre la sauvegarde multijoueur locale. Ne démarre pas la campagne.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['host','join','resume']},name:{type:'string'},country:{type:'string',enum:COUNTRIES.filter(c=>c.power).map(c=>c.id)},invitation:{type:'string'}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false},async execute(input){if(multiplayer.active)throw Error('Une session est déjà ouverte.');if(input.mode==='host'){if(multiplayer.hasSave())throw Error('Une sauvegarde multijoueur existe : reprenez-la ou confirmez son remplacement dans le menu.');await multiplayer.create(input.name||'Joueur',input.country||'FR');}else if(input.mode==='resume')await multiplayer.resume();else if(input.mode==='join')await multiplayer.connect(null,multiplayer.parseInvitation(input.invitation),input.name||'Joueur');else throw Error('Mode invalide.');return {active:multiplayer.active,status:multiplayer.status};}},{name:'start_sigma_multiplayer',title:'Lancer la campagne multijoueur',description:'L’hôte lance le salon avec au moins deux humains connectés ayant tous confirmé leur équipe ; les places restantes deviennent des PNJ.',inputSchema:common,annotations:{readOnlyHint:false},async execute(){return await multiplayer.command('start');}},{name:'read_sigma_campaign',title:'Lire la campagne Sigma',description:'Lire le tour, les agents et les renseignements connus du joueur. Ne révèle pas les secrets adverses.',inputSchema:common,annotations:{readOnlyHint:true},execute(){if(!state)throw Error('Aucune campagne commencée.');return E.publicState(state);}},{name:'stage_sigma_operation',title:'Affecter une opération',description:'Affecter gratuitement un ordre ; renfort facultatif de 6 crédits pour +10 points. Ne termine pas le tour.',inputSchema:{type:'object',properties:{agentId:{type:'string'},action:{type:'string',enum:Object.keys(ACTIONS).filter(id=>!ACTIONS[id].disabled)},target:{type:'string'},useCredits:{type:'boolean'}},required:['agentId','action'],additionalProperties:false},annotations:{readOnlyHint:false},async execute(input){if(!state||typeof input?.agentId!=='string'||!ACTIONS[input.action]||state.agents.find(a=>a.id===input.agentId)?.faction!==state.player)throw Error('Agent ou action invalide.');if(multiplayer.active){await multiplayer.command('assign',{id:input.agentId,type:input.action,target:input.target||null,useCredits:!!input.useCredits});return E.publicState(state);}E.assign(state,input.agentId,input.action,input.target||null,!!input.useCredits);stageSignal(state.agents.find(a=>a.id===input.agentId));persist();render();clearTimeout(toast.timer);orderFeedback(state,input.agentId);return E.publicState(state);}},{name:'advance_sigma_turn',title:'Terminer le tour',description:'En solo, termine le tour. En multijoueur, déclare le pays prêt ; la journée avance uniquement quand tous les humains sont prêts. Des agents peuvent rester inactifs.',inputSchema:common,annotations:{readOnlyHint:false},async execute(){if(!state)throw Error('Aucune campagne commencée.');if(multiplayer.active){await multiplayer.command('ready',{ready:true});return E.publicState(state);}const old=state.logId,turn=state.turn;clearSignals();E.advance(state);persist();render();report(old);turnSignals(state,turn);return E.publicState(state);}}];for(const tool of entries){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch(e){}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
applyPreferences();initMusic();render();loadMap();registerTools();queueMicrotask(async()=>{try{if(!await multiplayer.restoreSession()&&multiplayer.invitation())multiplayer.entry();}catch(e){toast(e.message);multiplayer.entry('host');}});

app.addEventListener('dragstart',event=>{const card=event.target.closest('[data-tech-drag]');if(!card||card.draggable===false||state?.ended||!event.dataTransfer)return;event.dataTransfer.setData('text/x-sigma-tech',card.dataset.techDrag);event.dataTransfer.effectAllowed='copy';});
app.addEventListener('dragover',event=>{const slot=event.target.closest('[data-tech-drop]');if(!slot||state?.ended||!event.dataTransfer?.types.includes('text/x-sigma-tech'))return;event.preventDefault();slot.classList.add('drag-over');});
app.addEventListener('dragleave',event=>{const slot=event.target.closest('[data-tech-drop]');if(slot&&!slot.contains(event.relatedTarget))slot.classList.remove('drag-over');});
app.addEventListener('dragend',()=>app.querySelectorAll('.drag-over').forEach(el=>el.classList.remove('drag-over')));
app.addEventListener('drop',event=>{const slot=event.target.closest('[data-tech-drop]');if(!slot||state?.ended)return;event.preventDefault();slot.classList.remove('drag-over');const type=event.dataTransfer?.getData('text/x-sigma-tech');if(!['ai','relay','logistics'].includes(type))return;const confirm=app.querySelector('.console-direct-card [data-cmd="tech"][data-id="'+type+'"]');if(confirm&&!confirm.disabled)confirm.click();});

setInterval(()=>{if(state)document.querySelectorAll('[data-campaign-clock]').forEach(el=>{el.textContent=formatDuration(elapsedMs(state));});},1000);

document.addEventListener('click',event=>{
 const sort=event.target.closest('[data-sort-column]');if(sort){sortTable(sort);return;}
 const wikiTab=event.target.closest('[data-wiki-tab]');if(wikiTab){wikiCategory=wikiTab.dataset.wikiTab;wikiQuery='';render();document.getElementById('wiki-search')?.focus();return;}
 const report=event.target.closest('[data-report-tab]');if(report){reportTab=report.dataset.reportTab;document.querySelectorAll('[data-report-panel]').forEach(el=>el.hidden=el.dataset.reportPanel!==reportTab);document.querySelectorAll('[data-report-tab]').forEach(el=>el.setAttribute('aria-pressed',String(el===report)));}
});
document.addEventListener('input',event=>{if(event.target.id==='wiki-search'){wikiQuery=event.target.value;document.getElementById('wiki-results').innerHTML=wikiResults(wikiCategory,wikiQuery);}});
document.addEventListener('change',event=>{if(event.target.id==='report-country'){reportCountry=event.target.value;document.getElementById('campaign-report').innerHTML=campaignSummary(state,{country:reportCountry,tab:reportTab});}});

// Access the manual without changing campaign state or issuing an order.
document.addEventListener('keydown',e=>{if(e.ctrlKey&&e.code==='Space'&&!e.repeat&&!revealSession&&!cinematic&&state&&!setup&&!menuOpen&&!(multiplayer.active&&multiplayer.snapshot?.phase!=='playing')){e.preventDefault();modal.close();view='wiki';render();}});
document.addEventListener('change',e=>{const id=e.target.dataset.timelineToggle;if(id)document.querySelectorAll('[data-timeline-team]').forEach(row=>{if(row.dataset.timelineTeam===id)row.hidden=!e.target.checked;});});

document.addEventListener('change',event=>{if(event.target.id!=='governmentCountry'||!state)return;const o=E.governmentOptions(state,'diplomacy',event.target.value),card=document.querySelector('.government-diplomacy');if(!card)return;card.querySelector('[data-government-cost]').textContent=o.cost??'—';card.querySelector('[data-cmd="government-favor"]').disabled=!!o.error;card.querySelector('.government-card-action>small').textContent=o.error||'Immédiat · aucun agent mobilisé';});

document.addEventListener('click',event=>{const mark=event.target.closest('[data-timeline-detail]');if(mark){const detail=document.getElementById('timeline-detail');if(detail){detail.textContent=mark.dataset.timelineLabel+' — '+mark.dataset.timelineDetail;document.querySelectorAll('.timeline-mark').forEach(b=>b.setAttribute('aria-pressed',String(b===mark)));}}});

document.addEventListener('click',event=>{const button=event.target.closest('[data-report-agent]');if(button){document.querySelectorAll('[data-agent-report]').forEach(card=>card.hidden=card.dataset.agentReport!==button.dataset.reportAgent);document.querySelectorAll('[data-report-agent]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}});

// Optional interface mod: all orders use the normal validated solo/host path.
initBureau({
 state:()=>state,
 exit:()=>{closeBureau();view='world';render();},
 ready:()=>bureauEnabled()&&!!state&&!menuOpen&&!setup&&view==='bureau'&&!(multiplayer.active&&multiplayer.snapshot?.phase!=='playing'),
 observer:()=>!!(multiplayer.active&&multiplayer.observer),
 readOnlyReason:()=>multiplayer.active?(multiplayer.observer?'Observateur : consultation uniquement':multiplayer.me?.ready?'Tour confirmé : modifiez vos ordres pour agir':multiplayer.pending?'Confirmation de l’hôte en attente':multiplayer.status?'Connexion au salon indisponible':''):'',
 notify:toast,
 async assign(p){
  if(!bureauEnabled()||!state)throw Error('Le Bureau des enquêtes est désactivé.');
  if(multiplayer.active){await multiplayer.command('assign',p);if(p.type==='drone')selectTechnology(null);render();return;}
  E.assign(state,p.id,p.type,p.target||null,p.useCredits);
  if(p.type==='drone')selectTechnology(null);
  stageSignal(state.agents.find(a=>a.id===p.id));persist();render();
 }
});

initCountryInquiry({
 state:()=>state,modal,showModal,notify:toast,openAgent,
 readOnlyReason:()=>!state||setup||menuOpen?'Campagne inactive':state.ended?'Campagne terminée':multiplayer.active?(multiplayer.observer?'Observateur : consultation uniquement':multiplayer.me?.ready?'Tour confirmé : modifiez vos ordres pour agir':multiplayer.pending?'Confirmation de l’hôte en attente':multiplayer.status?'Connexion au salon indisponible':''):'',
 async assign(p){
  if(!state||state.agents.find(a=>a.id===p.id)?.faction!==state.player)throw Error('Agent indisponible.');
  if(multiplayer.active){await multiplayer.command('assign',p);if(p.type==='drone')selectTechnology(null);render();return;}
  E.assign(state,p.id,p.type,p.target||null,p.useCredits);
  if(p.type==='drone')selectTechnology(null);
  stageSignal(state.agents.find(a=>a.id===p.id));persist();render();
 }
});
